CREATE TABLE IF NOT EXISTS mentor_assessments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, request_id UUID NOT NULL REFERENCES doubt_requests(id) ON DELETE CASCADE, mentor_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE, preparation engagement_scale NOT NULL, engagement engagement_scale NOT NULL, private_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (request_id, mentor_id));
